def slug(text):
    parts = []
    for char in text:
        if char.isascii() and char.islower() and char.isalpha():
            parts.append(char)
        elif char.isdigit():
            parts.append(char)
        else:
            parts.append("-")

    slug_text = "".join(parts).replace("--", "-")
    return slug_text.strip("-")
